-- Sathyagrahi Academy source-locked NEET Sep-Dec 2026 master study calendar.
-- Sources: approved Biology, Chemistry and Physics Master Plan PDFs.

create table if not exists public.academy_study_plan_chapters (
  id bigint generated by default as identity primary key,
  subject text not null check (subject in ('Biology','Chemistry','Physics')),
  plan_group text not null,
  unit_no integer not null,
  chapter_no integer not null,
  chapter text not null,
  study_start date not null,
  study_end date not null,
  r1_date date not null,
  r2_date date not null,
  r3_date date not null,
  r4_date date not null,
  planned_minutes integer not null default 240 check (planned_minutes > 0),
  source_year integer not null default 2026,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (subject, chapter_no),
  check (study_end >= study_start)
);

alter table public.academy_study_plan_chapters enable row level security;
revoke all on table public.academy_study_plan_chapters from anon, authenticated;
grant select on table public.academy_study_plan_chapters to authenticated;
grant select, insert, update, delete on table public.academy_study_plan_chapters to service_role;

drop policy if exists academy_study_plan_authenticated_read on public.academy_study_plan_chapters;
create policy academy_study_plan_authenticated_read on public.academy_study_plan_chapters for select to authenticated using (true);

on conflict (subject,chapter_no) do update set
  plan_group=excluded.plan_group, unit_no=excluded.unit_no, chapter=excluded.chapter,
  study_start=excluded.study_start, study_end=excluded.study_end,
  r1_date=excluded.r1_date, r2_date=excluded.r2_date, r3_date=excluded.r3_date, r4_date=excluded.r4_date,
  planned_minutes=excluded.planned_minutes, updated_at=now();

create or replace view public.academy_daily_study_plan with (security_invoker = true) as
select d::date plan_date,c.subject,c.plan_group,c.unit_no,c.chapter_no,c.chapter,'study'::text event_type,
       (d::date-c.study_start+1)::integer day_no,(c.study_end-c.study_start+1)::integer total_days,
       null::text revision_stage,c.planned_minutes
from public.academy_study_plan_chapters c
cross join lateral generate_series(c.study_start::timestamp,c.study_end::timestamp,interval '1 day') d
union all select c.r1_date,c.subject,c.plan_group,c.unit_no,c.chapter_no,c.chapter,'revision',null,null,'R1',c.planned_minutes from public.academy_study_plan_chapters c
union all select c.r2_date,c.subject,c.plan_group,c.unit_no,c.chapter_no,c.chapter,'revision',null,null,'R2',c.planned_minutes from public.academy_study_plan_chapters c
union all select c.r3_date,c.subject,c.plan_group,c.unit_no,c.chapter_no,c.chapter,'revision',null,null,'R3',c.planned_minutes from public.academy_study_plan_chapters c
union all select c.r4_date,c.subject,c.plan_group,c.unit_no,c.chapter_no,c.chapter,'revision',null,null,'R4',c.planned_minutes from public.academy_study_plan_chapters c;

revoke all on public.academy_daily_study_plan from anon, authenticated;
grant select on public.academy_daily_study_plan to authenticated, service_role;
